import{IMPORTED_BOUNDS}from'./geometry-data.js';
/** Rotate measured local geometry bounds once; art and rule collision share these boxes. */
export function importedBox(key,{x=0,y=0,z=0,scale=1,angle=0,roll=0}={},id=key){const b=IMPORTED_BOUNDS[key],points=[];for(const a of[b.min[0],b.max[0]])for(const c of[b.min[1],b.max[1]])for(const d of[b.min[2],b.max[2]]){const rx=a*Math.cos(roll)-c*Math.sin(roll),ry=a*Math.sin(roll)+c*Math.cos(roll);points.push({x:x+(rx*Math.cos(angle)+d*Math.sin(angle))*scale,y:y+ry*scale,z:z+(-rx*Math.sin(angle)+d*Math.cos(angle))*scale});}const minX=Math.min(...points.map(p=>p.x)),maxX=Math.max(...points.map(p=>p.x)),minZ=Math.min(...points.map(p=>p.z)),maxZ=Math.max(...points.map(p=>p.z));return{id,x:(minX+maxX)/2,z:(minZ+maxZ)/2,w:maxX-minX,d:maxZ-minZ,minY:Math.min(...points.map(p=>p.y)),maxY:Math.max(...points.map(p=>p.y)),kind:key};}
export function forestSolids(layout,height){return[...layout.trees.map((t,i)=>({...importedBox(t.key,{...t,y:height(t.x,t.z)},'tree-'+i),maxY:height(t.x,t.z)+8})),...layout.rocks.map((r,i)=>importedBox('boulder_low',{...r,y:height(r.x,r.z)-.06},'rock-'+i)),importedBox('DeadTree_1',{x:4.5,y:height(4.5,7)-.15,z:7,scale:.9,angle:Math.PI/2,roll:Math.PI/2},'fallen-log'),...[-1,1].map(side=>({id:'bridge-rail-'+side,x:side*1.255,z:-1.5,w:.23,d:3.6,minY:-.27,maxY:1.22,kind:'rail'})),...[-1,1].map(side=>({id:'gate-pillar-'+side,x:side*1.94,z:16.8,w:.74,d:.95,minY:height(0,16.8),maxY:4.2,kind:'stone'}))];}
export const FOREST_SWITCH={x:2.9,z:14.4};
export const FOREST_DOOR={id:'forest-door',x:0,z:16.8,w:3.1,d:.3,minY:0,maxY:3.1,kind:'door'};
export const WATER_ROUTES=[{x:-10,z:-1.5,w:17.6,d:3.7,navigationOnly:true},{x:10,z:-1.5,w:17.6,d:3.7,navigationOnly:true}];
